-- Generated by scripts/directory-csv-to-sql.mjs from supabase/directory/places.csv.
-- 279 listings from public sources. Every row records its source and
-- the date it was checked. verified_on stays null until the team confirms it.

-- The six hospitals from step 5 get a ref so the rows below update them.
update public.places p set ref = v.ref
from (values
  ('Al-Adan Hospital', 'hospital-al-adan-hospital-adan'),
  ('Al-Farwaniya Hospital', 'hospital-al-farwaniya-hospital-farwaniya'),
  ('Al-Jahra Hospital', 'hospital-al-jahra-hospital-jahra'),
  ('Mubarak Al-Kabeer Hospital', 'hospital-mubarak-al-kabeer-hospital-jabriya'),
  ('Al-Amiri Hospital', 'hospital-al-amiri-hospital-sharq'),
  ('Al-Sabah Hospital', 'hospital-al-sabah-hospital-shuwaikh')
) as v (name_en, ref)
where p.name_en = v.name_en and p.category = 'hospital' and p.ref is null;

on conflict (ref) do update set
  category = excluded.category,
  name_ar = excluded.name_ar,
  name_en = excluded.name_en,
  governorate = excluded.governorate,
  area_ar = excluded.area_ar,
  area_en = excluded.area_en,
  address = excluded.address,
  description_ar = excluded.description_ar,
  description_en = excluded.description_en,
  min_age_months = excluded.min_age_months,
  max_age_months = excluded.max_age_months,
  phone = excluded.phone,
  whatsapp = excluded.whatsapp,
  instagram = excluded.instagram,
  website = excluded.website,
  hours_ar = excluded.hours_ar,
  hours_en = excluded.hours_en,
  price_min_kwd = excluded.price_min_kwd,
  price_max_kwd = excluded.price_max_kwd,
  price_unit = excluded.price_unit,
  price_note_ar = excluded.price_note_ar,
  price_note_en = excluded.price_note_en,
  source_url = excluded.source_url,
  source_checked_on = excluded.source_checked_on,
  trending_until = excluded.trending_until,
  trending_note_ar = excluded.trending_note_ar,
  trending_note_en = excluded.trending_note_en;
